async () => { /* B0 baseline: every deduction global declared with its default, the runtime installed, nothing held, no verdicts, case open */ window.__toasts = window.__toasts || []; if (!window.__toastSpy) { const orig = window.gameAlert; window.gameAlert = (...a) => { window.__toasts.push(a); return orig ? orig(...a) : undefined; }; window.__toastSpy = true; } const G = window.__test.getState().globals; const R = window.deductionRuntime; const S = R && R.getState();
  const sus = ['ded_b_okoro','ded_b_lindqvist','ded_b_haddad','ded_b_morgan']; const facts = ['b_okoro_access','b_lindqvist_access','b_haddad_access','b_morgan_access','b_okoro_device','b_lindqvist_device','b_haddad_device','b_morgan_device','b_okoro_grievance','b_lindqvist_grievance','b_haddad_grievance','b_morgan_grievance'];
  return !!R && !!S && G.deduction_closed === false && JSON.stringify(G.scenario_triggers_fired) === '{}'
    && sus.every(s => G['deduction_verdict_' + s] === '' && G['deduction_outcome_' + s] === '')
    && facts.every(f => G['se_intel_' + f] === false) && G.b_heard_alarm === false && G.ded_b_tomas_influence === 0
    && S.state.closed === false && Object.keys(S.state.verdicts || {}).length === 0 && Object.values(S.decidable || {}).every(v => v === false); }

async () => { /* B0 board: four cards, every cell Hidden, six count lines '2 in this case, 0 found', the light stakes line plus briefText, no Make the call */ const mg = window.MinigameFramework.currentMinigame; const b = mg.getTestState().board; const txt = mg.container.textContent;
  const cells = b.suspects.flatMap(s => s.slots.flatMap(y => y.cells));
  return b.mode === 'deduction' && b.suspects.length === 4 && cells.length === 12 && cells.every(c => c.state === 'hidden')
    && (txt.match(/2 in this case, 0 found/g) || []).length === 6
    && /Name the wrong people, or miss someone, and the report will say so\./.test(txt)
    && !/Make the call/.test(txt) && !/\b(token|quest card|elder sign|the insider)\b/i.test(txt); }

async () => { /* B2 the complaint copy is handed over with no combat: in the notepad, t_b_complaint_copy fired, Lindqvist's grievance held; both grievance copies are now seen (Okoro from B1, Lindqvist here), so Haddad and Morgan clear by count elimination with their own grievance cells still hidden: one nudge toast each, none for Okoro or Lindqvist */ await new Promise(r => setTimeout(r, 500)); const G = window.__test.getState().globals; const R = window.deductionRuntime; const S = R && R.getState();
  const nudges = (window.__toasts || []).filter(a => /You have enough to decide about/.test(a[0] || ''));
  return G.se_intel_b_lindqvist_grievance === true && G.scenario_triggers_fired.t_b_complaint_copy === true && window.__test.getState().globals.b_heard_alarm === true
    && S.decidable.ded_b_haddad === true && S.decidable.ded_b_morgan === true && S.decidable.ded_b_okoro === false && S.decidable.ded_b_lindqvist === false
    && nudges.some(a => /Samira Haddad/.test(a[0])) && nudges.some(a => /Gwen Morgan/.test(a[0])) && nudges.length === 2; }

async () => { /* B4 mark Haddad clear with a reason, Okoro guilty with profile insider (through the runtime the board calls) */ const R = window.deductionRuntime;
  R.setMark('ded_b_haddad', 'clear', { because: ['b_haddad_grievance'] }); R.setMark('ded_b_okoro', 'guilty', { profile: 'insider' });
  const st = window.gameState.globalVariables.deduction_state; return st.marks.ded_b_haddad.mark === 'clear' && st.marks.ded_b_haddad.because[0] === 'b_haddad_grievance' && st.marks.ded_b_okoro.profile === 'insider'; }

async () => { /* B5 all twelve facts held, every suspect decidable, the truth matches the solution, no minigame left open by triggerOnInteract */ await new Promise(r => setTimeout(r, 500)); const G = window.__test.getState().globals; const R = window.deductionRuntime; const S = R && R.getState(); const facts = ['b_okoro_access','b_lindqvist_access','b_haddad_access','b_morgan_access','b_okoro_device','b_lindqvist_device','b_haddad_device','b_morgan_device','b_okoro_grievance','b_lindqvist_grievance','b_haddad_grievance','b_morgan_grievance'];
  return facts.every(f => G['se_intel_' + f] === true) && Object.values(S.decidable).every(v => v === true)
    && S.truth.ded_b_okoro === 'guilty' && ['ded_b_lindqvist','ded_b_haddad','ded_b_morgan'].every(s => S.truth[s] === 'clear') && !window.__test.getState().activeMinigame; }

async () => { /* B6 debrief after the phone closed: Okoro right_guilty with the Insider why line; the other three Not named and innocent, each failing a clause; Your note lines shown */ const mg = window.MinigameFramework.currentMinigame; const d = mg.getTestState().board.debrief; const txt = mg.container.textContent; const G = window.__test.getState().globals; const R = window.deductionRuntime; const S = R && R.getState();
  const card = id => d.cards.find(c => c.id === id);
  return G.deduction_closed === true && G.deduction_outcome_ded_b_okoro === 'right_guilty'
    && ['ded_b_lindqvist','ded_b_haddad','ded_b_morgan'].every(s => G['deduction_outcome_' + s] === 'right_clear' && card(s).verdictKind === 'none')
    && /Why: Insider: yes/.test(card('ded_b_okoro').text) && /Insider: no, no personal device/.test(card('ded_b_lindqvist').text)
    && /Not named/.test(txt) && /Your note/.test(txt) && !/You failed to/i.test(txt); }

async () => { /* B6 Finish: b_case_solved and b_case_closed completed, b_insider_named true, b_wrong_name false, the success screen says Case closed */ await new Promise(r => setTimeout(r, 1000)); const om = window.objectivesManager; const G = window.__test.getState().globals; const R = window.deductionRuntime; const S = R && R.getState();
  return om.taskIndex.b_case_solved.status === 'completed' && om.taskIndex.b_case_closed.status === 'completed' && G.b_insider_named === true && G.b_wrong_name === false
    && /Case closed/.test(document.body.textContent) && S.state.debriefSeen === true && S.state.debriefPending === false; }

async () => { /* B7 the board shows View the debrief and no mark can change */ const mg = window.MinigameFramework.currentMinigame; const before = JSON.stringify(window.gameState.globalVariables.deduction_state.marks);
  window.deductionRuntime.setMark('ded_b_morgan', 'guilty', { profile: 'insider' });
  return /View the debrief/.test(mg.container.textContent) && JSON.stringify(window.gameState.globalVariables.deduction_state.marks) === before; }
